const READ_ONLY_LIVE = {
  readOnlyHint: true,
  idempotentHint: true,
  openWorldHint: true,
} as const;

type ToolContract = {
  title: string;
  description: string;
  annotations: typeof READ_ONLY_LIVE;
  input: { keys: readonly string[]; required: readonly string[] };
  output: { keys: readonly string[]; required: readonly string[] };
  structuredContent: Record<string, unknown>;
};

